// Wrong Chat v2.6 — Self-Contained Production Server (Upload to GitHub Root with package.json!)
import express from "express";
import fs from "fs";
import http from "http";
import crypto from "crypto";
import path from "path";
import { WebSocketServer, WebSocket } from "ws";

const PORT = Number(process.env.PORT) || 10000;
const HOST = "0.0.0.0";

const EMBEDDED_ASSETS = {"/assets/index-Uw-SdWlM.css":{"mime":"text/css; charset=utf-8","b64":""},"/assets/index-aXADcuwv.js":{"mime":"application/javascript; charset=utf-8","b64":""},"/index.html":{"mime":"text/html; charset=utf-8","b64":""}};
const EMBEDDED_APK_B64 = "";
const APK_BUFFER = Buffer.from(EMBEDDED_APK_B64, "base64");

const DECODED_ASSETS = new Map();
for (const [routePath, meta] of Object.entries(EMBEDDED_ASSETS)) {
  DECODED_ASSETS.set(routePath, {
    mime: meta.mime,
    buf: Buffer.from(meta.b64, "base64"),
  });
}

const DB_FILE = path.resolve("./wrongchat-runtime-db.json");
const DEFAULT_DB = {
  users: {},
  pairings: {},
  sessions: {},
  userStates: {},
  updatedAt: new Date().toISOString(),
};

function loadDb() {
  try {
    if (fs.existsSync(DB_FILE)) {
      return { ...structuredClone(DEFAULT_DB), ...JSON.parse(fs.readFileSync(DB_FILE, "utf-8")) };
    }
  } catch {}
  return structuredClone(DEFAULT_DB);
}

function saveDb(db) {
  try {
    db.updatedAt = new Date().toISOString();
    fs.writeFileSync(DB_FILE, JSON.stringify(db), "utf-8");
  } catch {}
}

const db = loadDb();
const AVATAR_EMOJIS = ["🧑‍💻", "👩‍🎨", "🧑‍🚀", "🦋", "🦸‍♂️", "🌟", "🦊", "🐼"];
const AVATAR_GRADIENTS = [
  "from-emerald-400 via-teal-400 to-sky-400",
  "from-sky-400 via-cyan-300 to-indigo-400",
  "from-rose-400 via-amber-300 to-emerald-400",
  "from-teal-400 to-lime-300",
];

function hashPw(pw) {
  return crypto.createHash("sha256").update("wc_salt_v26:" + pw).digest("hex");
}
function sanitizeUser(u) {
  const { passwordHash, ...safe } = u;
  return { ...safe, email: u.identifier };
}

const app = express();
app.use((req, res, next) => {
  res.setHeader("Access-Control-Allow-Origin", "*");
  res.setHeader("Access-Control-Allow-Methods", "GET, POST, PUT, DELETE, OPTIONS");
  res.setHeader("Access-Control-Allow-Headers", "Content-Type, Authorization");
  if (req.method === "OPTIONS") return res.status(204).end();
  next();
});
app.use(express.json({ limit: "15mb" }));

app.get("/api/health", (_req, res) => {
  res.json({
    app: "Wrong Chat",
    status: "healthy",
    version: "2.6.0",
    botsRemoved: true,
    loginRevealStyle: "white-screen-bomb-blast-portal",
    mapEngine: "Leaflet + OpenStreetMap + Voyager + Satellite + Nominatim",
    registeredRealUsers: Object.keys(db.users).length,
    apkAvailable: true,
    apkFileName: "WrongChat-v2.6.apk",
    apkSizeBytes: APK_BUFFER.length,
    timestamp: new Date().toISOString(),
  });
});

app.post("/api/auth/register-or-login", (req, res) => {
  const rawIdentifier = String(
    req.body?.identifier || req.body?.email || req.body?.phone || req.body?.name || ""
  ).trim();
  const password = String(req.body?.password || "2580").trim() || "2580";
  const displayNameInput = String(req.body?.name || req.body?.displayName || "").trim();
  const phoneInput = String(req.body?.phone || "").trim();
  const avatarInput = String(req.body?.avatarEmoji || "").trim();

  if (!rawIdentifier) {
    return res.status(400).json({ error: "Please enter your name, phone number, or email." });
  }

  const normId = rawIdentifier.toLowerCase();
  const cleanDigits = normId.replace(/\s+/g, "");
  const existing = Object.values(db.users).find(
    (u) =>
      u.identifier.toLowerCase() === normId ||
      (cleanDigits.length >= 5 && u.phone && u.phone.replace(/\s+/g, "") === cleanDigits)
  );

  if (existing) {
    if (displayNameInput) existing.name = displayNameInput;
    if (phoneInput && phoneInput.length >= 5) existing.phone = phoneInput;
    if (avatarInput) existing.avatarEmoji = avatarInput;
    existing.online = true;
    existing.lastSeen = "Online now";
    const token = "wc_tok_" + crypto.randomBytes(16).toString("hex");
    db.sessions[token] = { userId: existing.id, phone: existing.phone, userName: existing.name, createdAt: Date.now() };
    saveDb(db);
    return res.json({ ok: true, token, user: sanitizeUser(existing) });
  }

  const userCount = Object.keys(db.users).length;
  const derivedName = displayNameInput || (rawIdentifier.includes("@") ? rawIdentifier.split("@")[0] : rawIdentifier);
  const userId = "usr_" + crypto.randomBytes(6).toString("hex");
  const aiCode = "WC-" + Math.floor(1000 + Math.random() * 9000) + "-" +
    derivedName.replace(/[^A-Za-z]/g, "").slice(0, 4).toUpperCase().padEnd(4, "X");

  const newUser = {
    id: userId,
    name: derivedName,
    identifier: rawIdentifier,
    phone: phoneInput || (rawIdentifier.includes("@") ? "+91 98000 00000" : rawIdentifier),
    username: "@" + (derivedName.toLowerCase().replace(/[^a-z0-9]/g, "") || "member"),
    passwordHash: hashPw(password),
    aiCode,
    avatarEmoji: avatarInput || AVATAR_EMOJIS[userCount % AVATAR_EMOJIS.length],
    avatarBg: AVATAR_GRADIENTS[userCount % AVATAR_GRADIENTS.length],
    lat: 26.8467,
    lng: 80.9462,
    accuracyMeters: 20,
    locationName: "Lucknow, Uttar Pradesh",
    online: true,
    lastSeen: "Online now",
    createdAt: Date.now(),
  };

  db.users[userId] = newUser;
  db.pairings[userId] = [];
  const token = "wc_tok_" + crypto.randomBytes(16).toString("hex");
  db.sessions[token] = { userId, phone: newUser.phone, userName: newUser.name, createdAt: Date.now() };
  saveDb(db);
  return res.json({ ok: true, token, user: sanitizeUser(newUser) });
});

app.get("/api/users/directory", (req, res) => {
  const excludeId = String(req.query.excludeId || "");
  const users = Object.values(db.users).filter((u) => u.id !== excludeId).map(sanitizeUser);
  res.json({ ok: true, users });
});

app.post("/api/users/pair", (req, res) => {
  const myUserId = String(req.body?.myUserId || "").trim();
  const targetQuery = String(req.body?.targetCodeOrId || "").trim();
  if (!targetQuery) return res.status(400).json({ error: "Enter AI Code or phone." });
  const qUpper = targetQuery.toUpperCase();
  const target = Object.values(db.users).find(
    (u) =>
      u.id !== myUserId &&
      (u.id === targetQuery ||
        u.aiCode.toUpperCase() === qUpper ||
        u.identifier.toLowerCase() === targetQuery.toLowerCase() ||
        u.phone.replace(/\s+/g, "") === targetQuery.replace(/\s+/g, ""))
  );
  if (!target) {
    return res.status(404).json({ error: "User not found with that AI Code yet." });
  }
  if (myUserId && db.users[myUserId]) {
    db.pairings[myUserId] = Array.from(new Set([...(db.pairings[myUserId] || []), target.id]));
    db.pairings[target.id] = Array.from(new Set([...(db.pairings[target.id] || []), myUserId]));
    saveDb(db);
    broadcastWs({ type: "user_paired", initiator: sanitizeUser(db.users[myUserId]), targetId: target.id });
  }
  res.json({ ok: true, targetUser: sanitizeUser(target) });
});

app.post("/api/users/gps", (req, res) => {
  const { userId, lat, lng, accuracyMeters, locationName } = req.body || {};
  if (userId && db.users[userId] && typeof lat === "number" && typeof lng === "number") {
    db.users[userId].lat = lat;
    db.users[userId].lng = lng;
    if (typeof accuracyMeters === "number") db.users[userId].accuracyMeters = accuracyMeters;
    if (locationName) db.users[userId].locationName = String(locationName);
    db.users[userId].online = true;
    saveDb(db);
    broadcastWs({ type: "gps_update", userId, lat, lng, accuracyMeters: db.users[userId].accuracyMeters, locationName: db.users[userId].locationName });
  }
  res.json({ ok: true });
});

app.get("/api/map/search", async (req, res) => {
  const q = String(req.query.q || "").trim();
  if (!q) return res.json({ ok: true, results: [] });
  try {
    const r = await fetch("https://nominatim.openstreetmap.org/search?format=json&limit=6&addressdetails=1&q=" + encodeURIComponent(q), {
      headers: { "User-Agent": "WrongChatRealMap/2.6", "Accept-Language": "en" },
    });
    const data = await r.json();
    res.json({ ok: true, results: Array.isArray(data) ? data : [] });
  } catch {
    res.json({ ok: false, results: [] });
  }
});

app.get("/api/map/reverse", async (req, res) => {
  const lat = Number(req.query.lat);
  const lng = Number(req.query.lng);
  if (!Number.isFinite(lat) || !Number.isFinite(lng)) return res.status(400).json({ ok: false });
  try {
    const r = await fetch("https://nominatim.openstreetmap.org/reverse?format=json&zoom=16&lat=" + lat + "&lon=" + lng, {
      headers: { "User-Agent": "WrongChatRealMap/2.6", "Accept-Language": "en" },
    });
    const data = await r.json();
    const addr = data?.address || {};
    const shortLabel = [addr.neighbourhood || addr.suburb || addr.road || addr.village, addr.city || addr.town || addr.state].filter(Boolean).join(", ") || (lat.toFixed(4) + "°, " + lng.toFixed(4) + "°");
    res.json({ ok: true, label: shortLabel });
  } catch {
    res.json({ ok: true, label: lat.toFixed(4) + "°, " + lng.toFixed(4) + "°" });
  }
});

app.get("/api/state", (req, res) => {
  const userId = String(req.query.userId || "");
  res.json({ ok: true, appState: userId ? db.userStates[userId] || null : null, updatedAt: db.updatedAt });
});

app.post("/api/state/sync", (req, res) => {
  const userId = String(req.body?.userId || "");
  if (userId && req.body?.state) {
    db.userStates[userId] = req.body.state;
    saveDb(db);
  }
  res.json({ ok: true, updatedAt: db.updatedAt });
});

const serveApk = (_req, res) => {
  res.setHeader("Content-Type", "application/vnd.android.package-archive");
  res.setHeader("Content-Disposition", "attachment; filename=\"WrongChat-v2.6.apk\"");
  res.setHeader("Content-Length", String(APK_BUFFER.length));
  res.end(APK_BUFFER);
};
app.get("/downloads/WrongChat-v2.6.apk", serveApk);
app.get("/downloads/WrongChat-v2.4.apk", serveApk);

app.get("*", (req, res) => {
  const cleanPath = req.path === "/" ? "/index.html" : req.path;
  const hit = DECODED_ASSETS.get(cleanPath) || DECODED_ASSETS.get("/index.html");
  res.setHeader("Content-Type", hit.mime);
  res.end(hit.buf);
});

const server = http.createServer(app);
const wss = new WebSocketServer({ server, path: "/ws" });
const socketUserMap = new Map();

function broadcastWs(payload, exclude) {
  const raw = JSON.stringify({ ...payload, relayedAt: Date.now() });
  wss.clients.forEach((client) => {
    if (client !== exclude && client.readyState === WebSocket.OPEN) client.send(raw);
  });
}

wss.on("connection", (socket) => {
  socket.send(JSON.stringify({ type: "welcome", engine: "Wrong Chat v2.6 Render Cloud Mesh", e2ee: true }));
  socket.on("message", (raw) => {
    try {
      const msg = JSON.parse(raw.toString());
      if (msg.type === "identify" && msg.userId) {
        socketUserMap.set(socket, String(msg.userId));
        if (db.users[msg.userId]) {
          db.users[msg.userId].online = true;
          saveDb(db);
        }
        broadcastWs({ type: "presence", userId: msg.userId, online: true }, socket);
        return;
      }
      if (msg.type === "gps_update" && msg.userId && db.users[msg.userId]) {
        db.users[msg.userId].lat = Number(msg.lat);
        db.users[msg.userId].lng = Number(msg.lng);
        if (msg.locationName) db.users[msg.userId].locationName = String(msg.locationName);
        saveDb(db);
      }
      broadcastWs(msg, socket);
    } catch {}
  });
  socket.on("close", () => {
    const uid = socketUserMap.get(socket);
    socketUserMap.delete(socket);
    if (uid && db.users[uid]) {
      db.users[uid].online = false;
      saveDb(db);
      broadcastWs({ type: "presence", userId: uid, online: false });
    }
  });
});

server.listen(PORT, HOST, () => {
  console.log("✨ Wrong Chat v2.6 Render Server LIVE on http://" + HOST + ":" + PORT);
});
